+// Helper function to convert a slice of alternating key-value pairs into a map
+func mapResults(pairs []string) map[string]string {
+	resultMap := make(map[string]string)
+	for i := 0; i < len(pairs); i += 2 {
+		resultMap[pairs[i]] = pairs[i+1]
+	}
+	return resultMap
+}
+
+// Helper function to convert a slice of interface{} to a slice of strings
+func convertToStringSlice(interfaces []interface{}) []string {
+	strings := make([]string, len(interfaces))
+	for i, v := range interfaces {
+		strings[i] = v.(string)
+	}
+	return strings
+}

