-	if object.AssertType(obj.TypeEncoding, object.ObjTypeByteArray) == nil ||
-		object.AssertType(obj.TypeEncoding, object.ObjTypeString) == nil ||
-		object.AssertType(obj.TypeEncoding, object.ObjTypeInt) == nil {
