-				count--
-			}
-		}
-	}
-
-	if count == 0 {
-		return clientio.Encode([]string{}, false)
-	}
-
-	members := make([]string, 0, len(resultSet))
-	for k := range resultSet {
-		members = append(members, k)
-	}
-	return clientio.Encode(members, false)
