-
-	// get all the keys
-	keys := args[2:]
-
-	// validation of commands
-	// if operation is not from enums, then error out
-	if !(operation == AND || operation == OR || operation == XOR || operation == NOT) {
-		return diceerrors.NewErrWithMessage(diceerrors.SyntaxErr)
