-	if operation == NOT {
-		if len(keys) != 1 {
-			return diceerrors.NewErrWithMessage("BITOP NOT must be called with a single source key.")
-		}
-		key := keys[0]
-		obj := store.Get(key)
-		if obj == nil {
-			return clientio.Encode(0, true)
-		}
