+func TestPFCountWatchWithSDK(t *testing.T) {
+	ctx, cancel := context.WithTimeout(context.Background(), defaultTimeout)
+	defer cancel()
+
+	publisher := getLocalSDK(t)
+	subscribers := setupSubscribers(t, 3)
+	defer cleanupSubscribers(subscribers)
+
+	// Clean up test key before starting
+	err := publisher.Del(ctx, pfCountWatchKey)
+	assert.NilError(t, err)
+
+	// Setup watch channels
+	channels := setupWatchChannels(t, ctx, subscribers)
+
+	t.Run("Basic PFCount Operations", func(t *testing.T) {
+		testPFCountOperations(t, ctx, publisher, channels)
+	})
+
+	t.Run("PFCount with Merge Operations", func(t *testing.T) {
+		testPFCountMergeOperations(t, ctx, publisher, channels)
+	})
+}
+
+func setupSubscribers(t *testing.T, count int) []watchSubscriber {
+	subscribers := make([]watchSubscriber, count)
+	for i := range subscribers {
+		subscribers[i].client = getLocalSDK(t)
+	}
+	return subscribers
+}
+
+func cleanupSubscribers(subscribers []watchSubscriber) {
+	for _, sub := range subscribers {
+		if sub.watch != nil {
+			sub.watch.Close()
+		}
+	}
+}
+
+func setupWatchChannels(t *testing.T, ctx context.Context, subscribers []watchSubscriber) []<-chan *dicedb.WatchResult {
+	channels := make([]<-chan *dicedb.WatchResult, len(subscribers))
+	
+	for i, subscriber := range subscribers {
+		watch := subscriber.client.WatchConn(ctx)
+		assert.Assert(t, watch != nil)
+		
+		firstMsg, err := watch.Watch(ctx, "PFCOUNT", pfCountWatchKey)
+		assert.NilError(t, err)
+		assert.Equal(t, firstMsg.Command, "PFCOUNT")
+		
+		subscribers[i].watch = watch
+		channels[i] = watch.Channel()
+	}
+	
+	return channels
+}
+
+func testPFCountOperations(t *testing.T, ctx context.Context, publisher *SDK, channels []<-chan *dicedb.WatchResult) {
+	for _, tc := range pfCountTestCases {
+		err := publisher.PFAdd(ctx, tc.Key, tc.Value)
+		assert.NilError(t, err)
+
+		verifyWatchResults(t, channels, tc.Result)
+	}
+}
+
+func testPFCountMergeOperations(t *testing.T, ctx context.Context, publisher *SDK, channels []<-chan *dicedb.WatchResult) {
+	for _, tc := range pfCountMergeTestCases {
+		// Clean up previous keys
+		err := publisher.Del(ctx, tc.DestKey1, tc.DestKey2)
+		assert.NilError(t, err)
+
+		// Add values to both keys
+		err = publisher.PFAdd(ctx, tc.DestKey1, tc.DestValue1...)
+		assert.NilError(t, err)
+		err = publisher.PFAdd(ctx, tc.DestKey2, tc.DestValue2...)
+		assert.NilError(t, err)
+
+		// Merge keys
+		err = publisher.PFMerge(ctx, pfCountWatchKey, tc.DestKey1, tc.DestKey2)
+		assert.NilError(t, err)
+
+		verifyWatchResults(t, channels, tc.Expected)
+	}
+}
+
+func verifyWatchResults(t *testing.T, channels []<-chan *dicedb.WatchResult, expected int64) {
+	for _, channel := range channels {
+		select {
+		case v := <-channel:
+			assert.Equal(t, "PFCOUNT", v.Command)
+			assert.Equal(t, watchFingerprint, v.Fingerprint)
+			assert.DeepEqual(t, expected, v.Data)
+		case <-time.After(defaultTimeout):
+			t.Fatal("timeout waiting for watch result")
+		}
+	}
+}

